template <class Sink>
__device__ inline void fan_oneway_out_trigger_warp(const GraphView& g, const Params& p, std::uint32_t e, std::uint32_t lane, Sink& out) {
  const std::uint32_t v_U = g.src[e];
  const std::uint32_t v_V = g.dst[e];
  const std::int64_t t = g.ts[e];
  const std::int64_t p_delta_fan = p.span;
  // visibility (SPEC v2 §6.1), once per trigger: stream sees eid <= e, timestamp sees ts <= t
  const std::uint32_t vis_e = p.ts_visibility ? kAnyEid : e;
  const std::int64_t vis_t = p.ts_visibility ? t : kNoUpper;
  if (v_U == v_V) return;
  if (lane == 0) {  // heavy kernel: nothing else reads this root check, so lane 0 runs it alone
    // stage oneway (difference, check)
    // difference U.out \ U.in over distinct nodes: scan U.out (T-CSR, distinct-first) and keep the elements whose probe of U.in (P-CSR) finds no edge; the scanned side is fixed (a difference is not symmetric)
    // no materialization: D is used only through len(), so the elements that pass the filters are counted
    // e1 in U.out: ts >= t - delta_fan + 1, visible: eid <= eid(e0) (stream) or ts <= t (timestamp), set once per trigger
    // e2 in U.in: ts >= t - delta_fan + 1, visible: eid <= eid(e0) (stream) or ts <= t (timestamp), set once per trigger
    std::int64_t len_D = 0;
    const std::int64_t lo_e1 = t - p_delta_fan + 1, hi_e1 = vis_t;
    const std::int64_t lo_e2 = t - p_delta_fan + 1, hi_e2 = vis_t;
    const Range r_e1 = g.out.range(v_U, lo_e1, hi_e1, vis_e);
    for (std::uint32_t j_e1 = r_e1.lo; j_e1 < r_e1.hi; ++j_e1) {
      if (!g.out.distinct_first(j_e1, r_e1.lo)) continue;
      const std::uint32_t v_Y = g.out.nbr[j_e1];
      if (v_Y == v_U) continue;
      if (g.pin.pair_exists(v_U, v_Y, lo_e2, hi_e2, vis_e) != kNoTs) continue;  // in U.in
      ++len_D;
    }
    const bool ok_oneway = len_D != 0;
    if (ok_oneway && len_D >= 2) out.emit(len_D);
  }
}

